function saveSvg(file_name) {
	let svgStr = `<svg width="${width}" height="${height}" xmlns="http://www.w3.org/2000/svg">\n`;

	for (let i = 0; i < PENS.length; i++) {
		svgStr += `<g id="${PENS[i].clr}" stroke="${PENS[i].clr}" fill="none">\n`;
		svgStr += svgArr[i];
		svgStr += `</g>\n`;
	}

	svgStr += `</svg>`;

	// save(svgStr.split("\n"), file_name + '.svg.txt');
	const blob = new Blob([svgStr], { type: 'image/svg+xml' });
	const url = URL.createObjectURL(blob);
	const link = document.createElement('a');
	link.href = url;
	link.download = file_name + ".svg";
	link.click();
	URL.revokeObjectURL(url);
}

