	Contributions: https://openprocessing.org/curation/78544
*/

const { Polygon } = EpiShapeSvg;

const NUM_LAYER = 2;
const MAR = 20;
let ROT = true; // rotation for hatches
const PENS = [{clr: "white", boost: 6}, {clr: "gold", boost: 3}, {clr: "purple", boost: 1}];
const BG = "#020208";
let pts, regions;

function setup() {
	createCanvas(windowWidth, windowHeight);
	describe("hatched voronoi cells with different colors and distance between lines" + ROT ? ", slightly rotation per cell" : "");
	frameRate(30);
	// noLoop() removed for animation
}

function init(bg = true) {
	// console.log(c2);
	const num = ~~sqrt(width + height);
	pts = new Array(num);
	for (let i = 0; i < pts.length; i++) pts[i] = new c2.Point(random(-0.1, 1.1) * width, random(-0.1, 1.1) * height);

	voronoi = new c2.Voronoi();
	voronoi.compute(pts); // console.log(voronoi);
	regions = voronoi.regions;

	ROT = random() < 0.5;

	if (bg) background(BG);
}

function mouseClicked() {
	if ((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) > 0.1 * width) redraw();
}

function draw() {
	svgArr = Array(PENS.length).fill("");

	for (let i = 0; i < NUM_LAYER; i++) {
		init(i == 0);
		for (let j = 0; j < voronoi.regions.length; j++) {			
			drawCell(voronoi.regions[j], pts[j]);
		} 
	}

	// noLoop() removed for animation
}

function drawCell(region, center) {
	push();

	const voronoiCell = new Polygon(region.vertices, true);
	// voronoiCell.drawShape();

	const w2 = ~~(width/2);
	const h2 = ~~(height/2);
	const yd = ~~random(6, 12);
	const multipleLinesPoly = new Polygon();
	for (let y = -h2; y < h2; y += yd) {
		multipleLinesPoly.addPtsArr([[-w2, y], [w2, y]]);
	}
	multipleLinesPoly.translate(center);

	if (ROT) multipleLinesPoly.rotate(map(noise(2+5*center.x/width + 5+5*center.y/height), 0, 1, -1, 1), center);
	const canvasPoly = new Polygon([[MAR, MAR], [width-MAR, MAR], [width-MAR, height-MAR], [MAR, height-MAR]], true);
	const hatchedLines = multipleLinesPoly.clipTo(voronoiCell).clipTo(canvasPoly);
	// const hathedLines = voronoiCell.getSkeleton(canvasPoly); // oopsie, not working

	const PEN = getRandom(PENS);
	stroke(PENS[PEN].clr);
	strokeWeight(2);
	hatchedLines.drawShape();

	svgArr[PEN] += hatchedLines.toSVG() + "\n";

	pop();
}

function getRandom(obj) {
	const probs = [];

	for (let i = 0; i < obj.length; i++) {
		for (let j = 0; j < obj[i].boost; j++) {
			probs.push(i);
		}
	}

	return random(probs);
}
